<script setup>
import { computed,onBeforeUnmount,ref,watch } from 'vue'
import { useRoute,useRouter,onBeforeRouteLeave } from 'vue-router'
import MarkdownIt from 'markdown-it';import DOMPurify from 'dompurify'
import { api } from '../api';import { session } from '../session'
import ValueEditor from '../components/ValueEditor.vue';import MediaPreview from '../components/MediaPreview.vue';import Chart from '../components/Chart.vue'
const route=useRoute(),router=useRouter(),operator=computed(()=>session.user?.role==='operator')
const product=ref(null),shops=ref([]),rounds=ref([]),roundId=ref(null),tab=ref('catalog'),competitors=ref([]),tasks=ref([]),materials=ref([]),contents=ref([]),proposals=ref([]),experiments=ref([]),reports=ref([])
const diagnosis=ref(null),creative=ref(null),proposal=ref(null),report=ref(null),diagnosisDraft=ref({}),creativeDraft=ref({}),proposalDraft=ref({}),reportDraft=ref({}),richDeltas=ref({})
const experimentId=ref(null),metrics=ref(null),error=ref(''),message=ref(''),busy=ref(false),dirty=ref(false),demo=ref(false),scenario=ref('success'),approvalComment=ref(''),executionNote=ref(''),selectedMaterials=ref([]),selectedActions=ref([])
const sku=ref({sku_code:'',color:'',size:''}),listing=ref({shop_id:null,platform_product_id:''}),mapping=ref({listing_id:null,sku_id:null,platform_sku_id:'',sale_price:'299.00',stock_quantity:0,warning_threshold:10}),competitor=ref({competitor_code:'',name:'',price:'269.00',selling_points:'',source_url:'',source_text:''}),stockDraft=ref({}),history=ref([])
const metricEditId=ref(null),productDraft=ref({}),skuDrafts=ref({}),mappingDrafts=ref({}),reviewScope=ref({date_from:'',date_to:''})
const metricDraft=ref({date:'2026-09-21',group_code:'A',impressions:0,clicks:0,orders:0,gmv:'0.00',ad_spend:'0.00',detail_visits:null,detail_bounces:null})
const dates=ref({date_from:'2026-09-21',date_to:'2026-09-27'}),shopId=ref(null),targets=ref({ctr:.022,conversion_rate:.03,roi:5,detail_bounce_rate:.4})
const currentRound=computed(()=>rounds.value.find(x=>x.id===Number(roundId.value)))
const versions=kind=>contents.value.filter(x=>x.kind===kind)
const clone=value=>JSON.parse(JSON.stringify(value))
const post=(path,body={})=>api.request(path,{method:'POST',body}),patch=(path,body)=>api.request(path,{method:'PATCH',body})
let epoch=0,pollTimer,polling=false,disposed=false
function markDirty(){dirty.value=true}
async function chooseContent(kind,id){const version=epoch;const result=await api.request(`/contents/${id}`);if(version!==epoch)return;if(kind==='diagnosis'){diagnosis.value=result;diagnosisDraft.value=clone(result.content)}else{creative.value=result;creativeDraft.value=clone(result.content);richDeltas.value=result.edited_content||{}}}
async function refresh(){const id=route.params.productId,version=++epoch;const [p,s,r,c]=await Promise.all([api.product(id),api.shops(),api.rounds(id),api.request(`/products/${id}/competitors`)]);if(version!==epoch)return;product.value=p;productDraft.value=clone({name:p.name,category:p.category,base_price:p.base_price,attributes:p.attributes});skuDrafts.value=Object.fromEntries(p.skus.map(x=>[x.id,clone(x.attributes)]));mappingDrafts.value=Object.fromEntries(p.listings.flatMap(l=>l.sku_mappings.map(m=>[m.id,{sale_price:m.sale_price,warning_threshold:m.warning_threshold}])));shops.value=s.items;rounds.value=r.items;competitors.value=c.items;if(!rounds.value.some(x=>x.id===Number(roundId.value)))roundId.value=r.items[0]?.id||null;shopId.value=shopId.value||p.listings[0]?.shop_id||s.items[0]?.id;await loadRound(version)}
async function loadRound(version=epoch){const index=currentRound.value?.resource_index;if(!index){contents.value=[];return}contents.value=index.contents;proposals.value=index.ad_proposals;experiments.value=index.experiments;reports.value=index.reviews;const [t,m]=await Promise.all([api.request(`/tasks?product_id=${product.value.id}&round_id=${roundId.value}`),api.request(`/materials?product_id=${product.value.id}&round_id=${roundId.value}&include_archived=true`)]);if(version!==epoch)return;tasks.value=t.items;materials.value=m.items;diagnosis.value=null;creative.value=null;proposal.value=null;report.value=null;metrics.value=null;for(const kind of ['diagnosis','creative']){if(version!==epoch)return;const found=versions(kind)[0];if(found)await chooseContent(kind,found.id)}if(version!==epoch)return;if(proposals.value[0])await chooseProposal(proposals.value[0].id);if(version!==epoch)return;if(reports.value[0])chooseReport(reports.value[0].id);experimentId.value=experiments.value[0]?.id||null;if(experimentId.value)await loadMetrics();dirty.value=false}
async function run(action,text='已保存',saveDraft=false){if(busy.value)return;if(dirty.value&&!saveDraft&&!window.confirm('这项操作会重新加载工作台。有未保存的编辑，仍要继续吗？'))return;busy.value=true;error.value='';message.value='';try{await action();dirty.value=false;await refresh();message.value=text}catch(e){error.value=[e.message,...(e.details||[]).map(x=>typeof x==='string'?x:x.message)].join('；')}finally{busy.value=false}}
async function switchRound(value){if(dirty.value&&!window.confirm('有未保存的编辑，仍要切换轮次吗？'))return;roundId.value=Number(value);epoch++;await loadRound()}
async function chooseProposal(id){const version=epoch;const result=await api.request(`/ad-proposals/${id}`);if(version!==epoch)return;proposal.value=result;const p=proposal.value;proposalDraft.value=clone({strategy:p.strategy,groups:p.groups,targets:p.targets,material_ids:p.material_ids,date_from:p.date_from,date_to:p.date_to});selectedMaterials.value=[...p.material_ids]}
function chooseReport(id){report.value=reports.value.find(x=>x.id===Number(id));reportDraft.value=clone({sections:report.value.sections,actions:report.value.actions});selectedActions.value=report.value.actions.map(x=>x.action_id)}
async function loadMetrics(){const version=epoch,id=experimentId.value;const result=await api.request(`/experiments/${id}/metrics`);if(version!==epoch||id!==experimentId.value)return;metrics.value=result;const exp=experiments.value.find(x=>x.id===Number(experimentId.value));executionNote.value=exp?.execution_note||'';reviewScope.value={date_from:exp?.date_from||'',date_to:exp?.date_to||''};metricDraft.value.date=exp?.date_from||metricDraft.value.date}
async function generate(kind){await run(()=>post(`/rounds/${roundId.value}/${kind==='diagnosis'?'diagnoses':'creatives'}/generate`,{demo_mode:demo.value,diagnosis_content_id:diagnosis.value?.id}),'内容已生成，审核编辑后再确认')}
async function saveContent(kind){const item=kind==='diagnosis'?diagnosis.value:creative.value;await run(()=>patch(`/contents/${item.id}`,{expected_version:item.version,content:kind==='diagnosis'?diagnosisDraft.value:creativeDraft.value,edited_content:kind==='creative'?richDeltas.value:null}),'新版本已保存，请重新确认',true)}
async function createTask(type,selection){await run(()=>post('/tasks',{creative_content_id:creative.value.id,selection_id:selection,task_type:type,demo_scenario:scenario.value}),'任务已排队，请保持独立 worker 运行')}
async function generateProposal(){await run(()=>post(`/rounds/${roundId.value}/ad-proposals/generate`,{shop_id:Number(shopId.value),diagnosis_content_id:diagnosis.value?.id,creative_content_id:creative.value?.id,material_ids:selectedMaterials.value,...dates.value,targets:targets.value,demo_mode:demo.value}),'建议已生成，请编辑、确认内容并提交主管')}
async function parseCompetitor(){await run(async()=>{const parsed=await post(`/products/${product.value.id}/competitors/parse`,{source_text:competitor.value.source_text,source_url:competitor.value.source_url});competitor.value={...competitor.value,...parsed.parsed_data,selling_points:parsed.parsed_data.selling_points.join('\n')}},'已解析，请核对并保存竞品')}
function editMetric(row){metricEditId.value=row.id;metricDraft.value=Object.fromEntries(Object.keys(metricDraft.value).map(k=>[k,row[k]]));dirty.value=true}
async function saveMetric(){const body={...metricDraft.value,detail_visits:metricDraft.value.detail_visits===''?null:metricDraft.value.detail_visits,detail_bounces:metricDraft.value.detail_bounces===''?null:metricDraft.value.detail_bounces};await run(async()=>{if(metricEditId.value){const {date,group_code,...values}=body;await patch('/metrics/'+metricEditId.value,values)}else await post('/experiments/'+experimentId.value+'/metrics',body);metricEditId.value=null},'经营数据已保存',true)}
async function adjust(mapping){await run(()=>post(`/sku-mappings/${mapping.id}/stock-adjustments`,{stock_quantity:Number(stockDraft.value[mapping.id]??mapping.stock_quantity),reason:'工作台手工调整'}))}
const displayMetric=(value,key)=>value==null?'不可计算':key==='roi'?`${Number(value).toFixed(2)} 倍`:`${(value*100).toFixed(2)}%`
const compareChart=computed(()=>({tooltip:{trigger:'axis'},legend:{},xAxis:{type:'category',data:['CTR','转化率','详情页跳失率']},yAxis:{type:'value',axisLabel:{formatter:'{value}%'}},series:[{name:'目标',type:'bar',data:['ctr','conversion_rate','detail_bounce_rate'].map(k=>(experiments.value.find(x=>x.id===Number(experimentId.value))?.targets[k]??0)*100)},{name:'实际',type:'bar',data:['ctr','conversion_rate','detail_bounce_rate'].map(k=>metrics.value?.metrics[k]==null?null:metrics.value.metrics[k]*100)}]}))
const markdown=new MarkdownIt({html:false});const preview=computed(()=>DOMPurify.sanitize(markdown.render(Object.entries(reportDraft.value.sections||{}).map(([key,value])=>`## ${key}\n\n${value.summary||''}\n\n${(value.facts||[]).join('\n\n')}`).join('\n\n'))))
async function poll(){if(disposed)return;if(!product.value||!roundId.value||busy.value||polling){pollTimer=setTimeout(poll,2000);return;}polling=true;const version=epoch;try{const query=`?product_id=${product.value.id}&round_id=${roundId.value}`;const [t,m]=await Promise.all([api.request(`/tasks${query}`),api.request(`/materials${query}&include_archived=true`)]);if(version===epoch){tasks.value=t.items;materials.value=m.items}}catch(e){error.value=e.message}finally{polling=false;const seconds=tasks.value[0]?.poll_interval_seconds||2;pollTimer=setTimeout(poll,seconds*1000)}}
watch(()=>route.params.productId,async()=>{roundId.value=null;dirty.value=false;try{await refresh()}catch(e){error.value=e.message}clearTimeout(pollTimer);pollTimer=setTimeout(poll,2000)},{immediate:true})
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}window.addEventListener('beforeunload',beforeUnload)
onBeforeRouteLeave(()=>!dirty.value||window.confirm('有未保存的内容，仍要离开吗？'))
onBeforeUnmount(()=>{disposed=true;epoch++;clearTimeout(pollTimer);window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template><section class="page workbench"><RouterLink to="/dashboard">← 返回大盘</RouterLink><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p><p v-if="busy">正在处理，请稍候…</p><template v-if="product"><div class="page-heading"><div><div class="eyebrow">PRODUCT WORKBENCH</div><h2>{{product.name}}</h2><p>{{product.product_code}} · {{product.category}} · ¥{{product.base_price}}</p></div><label>运营轮次<select :value="roundId" @change="switchRound($event.target.value)"><option v-for="r in rounds" :value="r.id" :key="r.id">第 {{r.round_no}} 轮 · {{r.phase}}</option></select></label></div><p v-if="currentRound?.source_report_id">来源报告 #{{currentRound.source_report_id}} · 已选行动 {{currentRound.selected_actions.map(x=>x.description).join('；')}}</p><div class="toolbar"><button v-for="[key,label] in [['catalog','档案与诊断'],['creative','创意与素材'],['advertising','投放与复盘']]" :key="key" :class="tab===key?'primary':'ghost'" @click="tab=key">{{label}}</button><label v-if="operator" class="inline"><input type="checkbox" v-model="demo">使用教学示例文字（不调用真实模型）</label></div><p class="muted">当前阶段：{{currentRound?.phase||'建档'}}。先确认诊断，再确认选定创意、制作和审核素材，随后提交投放审批。</p><button v-if="operator&&!rounds.length" class="primary" :disabled="busy" @click="run(()=>api.createRound(product.id),'首轮已创建')">创建首轮</button>
<div v-show="tab==='catalog'" class="stack"><section class="panel"><h3>商品档案、SKU 与店铺上架</h3><details v-if="operator"><summary>编辑商品基础信息</summary><ValueEditor v-model="productDraft" @update:model-value="markDirty"/><button class="primary" :disabled="busy" @click="run(()=>patch('/products/'+product.id,productDraft),'商品档案已保存',true)">保存档案</button></details><div v-for="s in product.skus" :key="s.id" class="list-row"><b>{{s.sku_code}}</b><span>{{JSON.stringify(s.attributes)}}</span><details v-if="operator"><summary>编辑规格</summary><ValueEditor v-model="skuDrafts[s.id]" @update:model-value="markDirty"/><button class="subtle" :disabled="busy" @click="run(()=>patch('/skus/'+s.id,{attributes:skuDrafts[s.id]}),'规格已保存',true)">保存规格</button></details><button v-if="operator" class="subtle" @click="run(()=>patch(`/products/${product.id}`,{main_sku_id:s.id}))">设为主推规格</button></div><form v-if="operator" class="form-grid" @submit.prevent="run(()=>post(`/products/${product.id}/skus`,{sku_code:sku.sku_code,attributes:{color:sku.color,size:sku.size}}))"><label>SKU 编码<input v-model="sku.sku_code" required></label><label>颜色<input v-model="sku.color" required></label><label>尺码<input v-model="sku.size" required></label><button class="primary" :disabled="busy">新增规格</button></form><form v-if="operator" class="form-grid" @submit.prevent="run(()=>post(`/products/${product.id}/listings`,listing))"><label>关联店铺<select v-model="listing.shop_id" required><option v-for="s in shops" :value="s.id" :key="s.id">{{s.name}}</option></select></label><label>平台商品标识<input v-model="listing.platform_product_id" required></label><button class="primary" :disabled="busy">关联店铺</button></form><div v-for="l in product.listings" :key="l.id"><h4>{{shops.find(x=>x.id===l.shop_id)?.name}} · {{l.platform_product_id}} · {{l.on_sale?'在售':'已下架'}}<button v-if="operator" class="subtle" :disabled="busy" @click="run(()=>patch('/listings/'+l.id,{on_sale:!l.on_sale}))">{{l.on_sale?'下架':'上架'}}</button></h4><div class="table-scroll"><table><thead><tr><th>平台 SKU</th><th>售价</th><th>库存／阈值</th><th>库存调整</th></tr></thead><tbody><tr v-for="m in l.sku_mappings" :key="m.id"><td>{{m.platform_sku_id}}</td><td>¥{{m.sale_price}}<details v-if="operator"><summary>编辑售价／阈值</summary><label>售价<input v-model="mappingDrafts[m.id].sale_price" @input="markDirty"></label><label>预警阈值<input type="number" min="0" v-model.number="mappingDrafts[m.id].warning_threshold" @input="markDirty"></label><button class="subtle" :disabled="busy" @click="run(()=>patch('/sku-mappings/'+m.id,mappingDrafts[m.id]),'映射已保存',true)">保存</button></details></td><td :class="m.stock_quantity<=m.warning_threshold?'error':''">{{m.stock_quantity}} / {{m.warning_threshold}}</td><td><template v-if="operator"><input type="number" min="0" v-model="stockDraft[m.id]" :placeholder="String(m.stock_quantity)"><button :disabled="busy" class="subtle" @click="adjust(m)">保存目标库存</button></template><button class="subtle" @click="api.request(`/sku-mappings/${m.id}/stock-movements`).then(x=>history=x.items).catch(e=>error=e.message)">查看流水</button></td></tr></tbody></table></div></div><form v-if="operator" class="form-grid" @submit.prevent="run(()=>post(`/listings/${mapping.listing_id}/sku-mappings`,mapping))"><label>上架记录<select v-model="mapping.listing_id" required><option v-for="l in product.listings" :value="l.id" :key="l.id">{{shops.find(x=>x.id===l.shop_id)?.name}}</option></select></label><label>统一 SKU<select v-model="mapping.sku_id" required><option v-for="s in product.skus" :value="s.id" :key="s.id">{{s.sku_code}}</option></select></label><label>平台 SKU 标识<input v-model="mapping.platform_sku_id" required></label><label>售价<input v-model="mapping.sale_price" required></label><label>目标库存<input type="number" min="0" v-model.number="mapping.stock_quantity"></label><label>预警阈值<input type="number" min="0" v-model.number="mapping.warning_threshold"></label><button class="primary" :disabled="busy">新增映射</button></form><div v-if="history.length" class="table-scroll"><table><thead><tr><th>时间</th><th>前值</th><th>后值</th><th>差额</th><th>来源／原因</th></tr></thead><tbody><tr v-for="h in history" :key="h.id"><td>{{h.created_at}}</td><td>{{h.before_quantity}}</td><td>{{h.after_quantity}}</td><td>{{h.delta}}</td><td>{{h.source}} · {{h.reason}}</td></tr></tbody></table></div></section>
<section class="panel"><h3>竞品录入与核对</h3><div v-for="c in competitors" :key="c.id" class="list-row"><b>{{c.name}} · ¥{{c.price}}</b><span>{{c.verification_status==='verified'?'已核对':'待核对'}}</span><button v-if="operator" :disabled="busy" class="subtle" @click="run(()=>patch(`/competitors/${c.id}`,{verification_status:'verified'}))">确认核对</button></div><form v-if="operator" class="form-grid" @submit.prevent="run(()=>post(`/products/${product.id}/competitors`,{...competitor,selling_points:competitor.selling_points.split('\n').filter(Boolean)}))"><label>竞品编码<input v-model="competitor.competitor_code" required></label><label>名称<input v-model="competitor.name" required></label><label>售价<input v-model="competitor.price" required></label><label>公开来源链接<input v-model="competitor.source_url"></label><label>卖点（每行一个）<textarea v-model="competitor.selling_points"></textarea></label><label>公开商品文本<textarea v-model="competitor.source_text"></textarea></label><button type="button" class="ghost" :disabled="busy||!competitor.source_text" @click="parseCompetitor">解析文本</button><button class="primary" :disabled="busy">保存为待核对竞品</button></form></section>
<section class="panel"><div class="toolbar"><h3>智能诊断</h3><button v-if="operator" class="primary" :disabled="busy||!roundId" @click="generate('diagnosis')">{{demo?'生成教学示例':'调用模型生成诊断'}}</button><select v-if="versions('diagnosis').length" :value="diagnosis?.id" @change="chooseContent('diagnosis',Number($event.target.value))"><option v-for="c in versions('diagnosis')" :value="c.id" :key="c.id">诊断 v{{c.version}} · {{c.status}}</option></select></div><template v-if="diagnosis"><p>{{diagnosis.content.generation_mode==='real'?'真实文字模型结果':'教学示例文字'}} · {{diagnosis.status}}</p><ValueEditor v-model="diagnosisDraft" :disabled="!operator||busy" @update:model-value="markDirty"/><div v-if="operator" class="toolbar"><button :disabled="busy" class="primary" @click="saveContent('diagnosis')">保存为新版本</button><button :disabled="busy||dirty||diagnosis.status==='archived'" class="ghost" @click="run(()=>post(`/contents/${diagnosis.id}/confirm`,{expected_version:diagnosis.version}))">确认诊断</button><button :disabled="busy" class="subtle" @click="run(()=>post(`/contents/${diagnosis.id}/archive`,{expected_version:diagnosis.version}))">归档</button></div></template><p v-else>请先录入并核对竞品，再生成诊断。</p></section></div>
<div v-show="tab==='creative'" class="stack"><section class="panel"><div class="toolbar"><h3>主图与视频创意</h3><button v-if="operator" class="primary" :disabled="busy||diagnosis?.status!=='confirmed'" @click="generate('creative')">{{demo?'生成教学示例':'调用模型生成创意'}}</button><select v-if="versions('creative').length" :value="creative?.id" @change="chooseContent('creative',Number($event.target.value))"><option v-for="c in versions('creative')" :value="c.id" :key="c.id">创意 v{{c.version}} · {{c.status}}</option></select></div><template v-if="creative"><p>{{creative.content.generation_mode==='real'?'真实模型结果':'教学示例文字'}} · {{creative.status}}</p><ValueEditor :key="creative.id" :deltas="richDeltas" v-model="creativeDraft" :disabled="!operator||busy" @update:model-value="markDirty" @rich-change="(p,d)=>richDeltas[p]=d"/><h4>选择要制作的方案</h4><div class="toolbar"><label v-for="item in creativeDraft.image_directions" :key="item.selection_id" class="inline"><input type="checkbox" v-model="creativeDraft.selected_image_ids" :value="item.selection_id" :disabled="!operator" @change="markDirty">主图：{{item.title}}</label><label v-for="item in creativeDraft.video_scripts" :key="item.selection_id" class="inline"><input type="checkbox" v-model="creativeDraft.selected_video_ids" :value="item.selection_id" :disabled="!operator" @change="markDirty">视频：{{item.title}}</label></div><div v-if="operator" class="toolbar"><button class="primary" :disabled="busy" @click="saveContent('creative')">保存选定方案为新版本</button><button class="ghost" :disabled="busy||dirty||creative.status==='archived'" @click="run(()=>post(`/contents/${creative.id}/confirm`,{expected_version:creative.version}))">确认创意版本</button><button class="subtle" :disabled="busy" @click="run(()=>post(`/contents/${creative.id}/archive`,{expected_version:creative.version}))">归档</button></div><div v-if="operator&&creative.status==='confirmed'" class="toolbar"><label>教学任务路径<select v-model="scenario"><option value="success">成功</option><option value="fail_once">首次失败后重试成功</option><option value="always_fail">持续失败</option><option value="timeout">执行超时</option><option value="late_result">迟到结果（可取消）</option></select></label><button v-for="id in creative.content.selected_image_ids" :key="id" class="primary" :disabled="busy" @click="createTask('image',id)">制作主图 {{id}}</button><button v-for="id in creative.content.selected_video_ids" :key="id" class="primary" :disabled="busy" @click="createTask('video',id)">制作视频 {{id}}</button></div></template><p v-else>先确认诊断，至少生成 3 组主图方向及 3 套视频脚本。</p></section>
<section class="panel"><h3>任务时间线</h3><p>排队等待与执行分开记录；每项任务使用提交时的超时和重试配置。</p><article v-for="t in tasks" :key="t.id" class="task-card"><div class="toolbar"><b>#{{t.id}} {{t.task_type==='image'?'图片':'视频'}} · {{t.status}}</b><span>排队：{{t.queued_at}}</span><button v-if="operator&&['pending','running'].includes(t.status)" class="subtle" :disabled="busy" @click="run(()=>post(`/tasks/${t.id}/cancel`))">取消</button><button v-if="operator&&t.retry_available" class="subtle" :disabled="busy" @click="run(()=>post(`/tasks/${t.id}/retry`))">人工重试</button></div><p v-if="t.error_reason" class="error">{{t.error_reason}}</p><ol><li v-for="a in t.attempts" :key="a.id">第 {{a.attempt_no}} 次：{{a.status}} · 开始 {{a.started_at}} · 截止 {{a.deadline_at}} · {{a.error_reason}}</li></ol></article><p v-if="!tasks.length">尚无任务。</p></section>
<section class="panel"><h3>商品素材库</h3><div class="material-grid"><article v-for="m in materials" :key="m.id" class="material-card"><MediaPreview :material="m"/><p>#{{m.id}} · 创意 #{{m.creative_content_id}} · v{{m.version}} · {{m.review_status}}{{m.archived_at?' · 已归档':''}}</p><p>标签：{{m.tags?.join('、')}}</p><div v-if="operator&&!m.archived_at" class="toolbar"><button class="subtle" :disabled="busy" @click="run(()=>post(`/materials/${m.id}/review`,{decision:'usable',comment:'运营核验通过'}))">审核可用</button><button class="subtle" :disabled="busy" @click="run(()=>post(`/materials/${m.id}/review`,{decision:'rejected',comment:'需调整创意重新制作'}))">驳回</button><button class="subtle" :disabled="busy" @click="run(()=>patch(`/materials/${m.id}/tags`,{tags:(window.prompt('标签，以逗号分隔',m.tags?.join(',')||'')||'').split(',').map(x=>x.trim()).filter(Boolean)}))">打标</button><button class="subtle" :disabled="busy" @click="run(()=>post(`/materials/${m.id}/archive`))">归档</button></div><details><summary>审核记录</summary><p v-for="(h,i) in m.review_history" :key="i">{{h.reviewed_at}} · 用户 #{{h.reviewed_by}} · {{h.decision}} · {{h.comment}}</p></details></article></div></section></div>
<div v-show="tab==='advertising'" class="stack"><section class="panel"><h3>投放建议与主管审批</h3><template v-if="operator"><div class="form-grid"><label>投放店铺<select v-model="shopId"><option v-for="l in product.listings" :value="l.shop_id" :key="l.id">{{shops.find(x=>x.id===l.shop_id)?.name}}</option></select></label><label>开始日期<input type="date" v-model="dates.date_from"></label><label>结束日期<input type="date" v-model="dates.date_to"></label></div><h4>选择审核可用的素材</h4><div class="toolbar"><label v-for="m in materials.filter(x=>x.review_status==='usable'&&!x.archived_at)" :key="m.id" class="inline"><input type="checkbox" v-model="selectedMaterials" :value="m.id">#{{m.id}} {{m.material_type}}</label></div><ValueEditor v-model="targets"/><button class="primary" :disabled="busy||!selectedMaterials.length||diagnosis?.status!=='confirmed'||creative?.status!=='confirmed'" @click="generateProposal">{{demo?'生成示例建议':'调用模型生成建议'}}</button></template><select v-if="proposals.length" :value="proposal?.id" @change="chooseProposal(Number($event.target.value))"><option v-for="p in proposals" :key="p.id" :value="p.id">建议 v{{p.version}} · {{p.status}}</option></select><template v-if="proposal"><p>{{proposal.strategy.generation_mode==='real'?'真实模型建议':'教学示例建议'}} · {{proposal.status}} · {{proposal.content_confirmed?'内容已确认':'内容未确认'}}</p><ValueEditor v-model="proposalDraft" :disabled="!operator||busy" @update:model-value="markDirty"/><div v-if="operator" class="toolbar"><button class="primary" :disabled="busy" @click="run(()=>patch(`/ad-proposals/${proposal.id}`,{expected_version:proposal.version,...proposalDraft}),'建议新版本已保存，请重新确认与审批',true)">保存为新版本</button><button class="ghost" :disabled="busy||dirty||proposal.status!=='draft'" @click="run(()=>post(`/ad-proposals/${proposal.id}/confirm`,{expected_version:proposal.version}))">确认内容</button><button class="primary" :disabled="busy||dirty||!proposal.content_confirmed||proposal.status!=='draft'" @click="run(()=>post(`/ad-proposals/${proposal.id}/submit`,{expected_version:proposal.version}))">提交主管审批</button><button class="subtle" :disabled="busy" @click="run(()=>post(`/ad-proposals/${proposal.id}/archive`,{expected_version:proposal.version}))">归档</button></div><template v-if="!operator&&proposal.status==='pending_approval'"><label>审批意见<textarea v-model="approvalComment"></textarea></label><div class="toolbar"><button class="primary" :disabled="busy" @click="run(()=>post(`/ad-proposals/${proposal.id}/approve`,{expected_version:proposal.version,comment:approvalComment}))">批准并建立课堂实验</button><button class="ghost" :disabled="busy||!approvalComment.trim()" @click="run(()=>post(`/ad-proposals/${proposal.id}/reject`,{expected_version:proposal.version,comment:approvalComment}))">驳回</button></div></template><p v-for="a in proposal.approvals" :key="a.id">{{a.created_at}} · 审批人 #{{a.actor_id}} · {{a.decision}} · {{a.comment}}</p></template><p>课堂模拟与人工执行备注；批准不会触发外部广告投放或扣费。</p></section>
<section v-if="experiments.length" class="panel"><h3>经营数据回填与目标对比</h3><label>批准的实验<select v-model="experimentId" @change="loadMetrics"><option v-for="e in experiments" :key="e.id" :value="e.id">EXP-{{e.id}} · {{e.date_from}}—{{e.date_to}}</option></select></label><template v-if="metrics"><div class="metric-grid"><article v-for="(value,key) in metrics.metrics" :key="key"><span>{{key}}</span><strong>{{displayMetric(value,key)}}</strong></article></div><Chart :option="compareChart"/><label>课堂模拟执行备注<textarea v-model="executionNote" :disabled="!operator"></textarea></label><button v-if="operator" class="ghost" :disabled="busy" @click="run(()=>patch(`/experiments/${experimentId}/execution-note`,{execution_note:executionNote}))">保存执行备注</button><form v-if="operator" class="form-grid" @submit.prevent="saveMetric"><label v-for="(value,key) in metricDraft" :key="key">{{key}}<input v-if="key==='date'" type="date" v-model="metricDraft[key]" :disabled="Boolean(metricEditId)" required><input v-else-if="key==='group_code'" v-model="metricDraft[key]" :disabled="Boolean(metricEditId)" required><input v-else-if="['gmv','ad_spend'].includes(key)" v-model="metricDraft[key]" required><input v-else type="number" min="0" v-model.number="metricDraft[key]" :required="!key.startsWith('detail_')"></label><button class="primary" :disabled="busy">{{metricEditId?'保存修正数据':'保存每日数据'}}</button><button v-if="metricEditId" type="button" class="ghost" @click="metricEditId=null;dirty=false">退出修正</button></form><RouterLink to="/imports">通过 Excel/CSV 批量回填</RouterLink><div class="table-scroll"><table><thead><tr><th>日期／组</th><th>曝光</th><th>点击</th><th>订单</th><th>GMV</th><th>花费</th></tr></thead><tbody><tr v-for="m in metrics.items" :key="m.id"><td>{{m.date}} / {{m.group_code}}</td><td>{{m.impressions}}</td><td>{{m.clicks}}</td><td>{{m.orders}}</td><td>{{m.gmv}}</td><td>{{m.ad_spend}}</td><td v-if="operator"><button class="subtle" :disabled="busy" @click="editMetric(m)">修正数据</button></td></tr></tbody></table></div><div v-if="operator" class="form-grid"><label>复盘范围开始<input type="date" v-model="reviewScope.date_from"></label><label>复盘范围结束<input type="date" v-model="reviewScope.date_to"></label></div><button v-if="operator" class="primary" :disabled="busy" @click="run(()=>post(`/experiments/${experimentId}/close-period`,{demo_mode:demo,...reviewScope}),'数据范围已确认，五部分复盘已生成')">确认周期数据并生成复盘</button></template></section>
<section v-if="reports.length" class="panel"><h3>闭环复盘与下一轮</h3><select :value="report?.id" @change="chooseReport(Number($event.target.value))"><option v-for="r in reports" :key="r.id" :value="r.id">报告 v{{r.version}} · {{r.status}}</option></select><template v-if="report"><p>{{report.snapshot.generation_mode==='real'?'真实模型分析':'教学示例分析'}}。指标及来源快照保留在当前版本。</p><div class="section-grid"><ValueEditor v-model="reportDraft" :disabled="!operator||busy" @update:model-value="markDirty"/><article class="markdown-preview" v-html="preview"></article></div><div v-if="operator" class="toolbar"><button class="primary" :disabled="busy" @click="run(()=>patch(`/reviews/${report.id}`,{expected_version:report.version,...reportDraft}),'报告新版本已保存',true)">保存新报告版本</button><button class="ghost" :disabled="busy||dirty" @click="run(()=>post(`/reviews/${report.id}/confirm`,{expected_version:report.version}))">确认报告</button><button class="subtle" :disabled="busy" @click="run(()=>post(`/reviews/${report.id}/archive`,{expected_version:report.version}))">归档</button></div><div v-if="operator&&report.status==='confirmed'"><label v-for="a in report.actions" :key="a.action_id" class="inline"><input type="checkbox" v-model="selectedActions" :value="a.action_id">{{a.description}}</label><button class="primary" :disabled="busy||!selectedActions.length" @click="run(async()=>{const result=await post(`/reviews/${report.id}/next-round`,{expected_version:report.version,action_ids:selectedActions,demo_mode:demo});roundId=result.round.id;tab='catalog'},'优化行动已进入下一轮诊断')">带选定行动创建下一轮诊断</button></div></template></section></div>
</template></section></template>
